proc ::mem_ss_pkg::util::get_sysinfo_params {} {
   return [list \
      [list @                                   TYPE        SYSTEM_INFO          SYSTEM_INFO_TYPE        SYSTEM_INFO_ARG            VISIBLE ] \
      [list SYSINFO_BOARD                       string      BOARD                NOVAL                   NOVAL                      false   ] \
      [list SYSINFO_BOARD_TRAIT                 string      BOARD_TRAIT          NOVAL                   NOVAL                      false   ] \
      [list SYSINFO_DEVICE                      string      DEVICE               NOVAL                   NOVAL                      false   ] \
      [list SYSINFO_DEVICE_FAMILY               string      DEVICE_FAMILY        NOVAL                   NOVAL                      false   ] \
      [list SYSINFO_DEVICE_SPEEDGRADE           string      DEVICE_SPEEDGRADE    NOVAL                   NOVAL                      false   ] \
      [list SYSINFO_DEVICE_DIE_REVISIONS        string_list NOVAL                DEVICE_DIE_REVISIONS    NOVAL                      false   ] \
      \
      \
      [list SYSINFO_DEVICE_TEMPERATURE_GRADE    string      NOVAL                PART_TRAIT              DEVICE_TEMPERATURE_GRADE   false   ] \
      [list SYSINFO_DEVICE_POWER_MODEL          string      NOVAL                PART_TRAIT              DEVICE_POWER_MODEL         false   ] \
      [list SYSINFO_SUPPORTS_VID                string      NOVAL                PART_TRAIT              SUPPORTS_VID               false   ] \
      [list SYSINFO_DEVICE_IOBANK_REVISION      string      NOVAL                PART_TRAIT              DEVICE_IOBANK_REVISION     false   ] \
   ]
}

proc ::mem_ss_pkg::util::create_device_features {} {
   table create device_features [list \
      [list @              VALUE__EXPR                                                             ]\
      [list family         {[eval {
                              if {[pval SYSINFO_DEVICE_DIE_REVISIONS] == ""} {
                                 set returnvalue "fp"
                              } else {
                                 switch -glob -- [lsearch -glob -inline [pval SYSINFO_DEVICE_DIE_REVISIONS] "MAIN_*"] {
                                    MAIN_FM[0-9]*  { set returnvalue "fm"  }
                                    MAIN_FP*       { set returnvalue "fp"  }
                                    MAIN_SM*       {
                                       switch -- "A" {
                                          A        { set returnvalue "smp" }
                                          B        { set returnvalue "sm"  }
                                       }
                                    }
                                    MAIN_FMM*      { set returnvalue "fmm" }
                                    default     { log ie "Failed to identify FPGA family" }
                                 }
                              }
                              set returnvalue
                           }]}                                                                     ] \
      [list iobank         {[pval SYSINFO_DEVICE_IOBANK_REVISION]}                                 ] \
      [list has_hbm        {[lsearch -glob [pval SYSINFO_DEVICE_DIE_REVISIONS] "UIB_HBM*"] != -1}  ] \
      [list has_hps        {[lsearch -regexp [list "with HPS"] {with ((?!without).)*HPS}] != -1}   ] \
      [list has_noc        {[table get device_features -> family -> VALUE] in [list fp]}           ] \
   ]
}

