proc ::mem_ss_pkg::util::create_parameters {table_data} {
   set params [table create private_params $table_data]

   set ip_core         [lindex [table rows package] 0]
   set ip_families     [list]
   foreach fam [table cols family_features] {
      if {$ip_core == [table get family_features -> IP_CORE -> $fam]} {
         lappend ip_families $fam
      }
   }

   foreach param $params {
      set param_families      [table get private_params -> $param -> __FAMILY]
      set visible             [table get private_params -> $param -> VISIBLE]
      set visible_expr        [table get private_params -> $param -> VISIBLE__EXPR]
      set enabled             [table get private_params -> $param -> ENABLED]
      set enabled_expr        [table get private_params -> $param -> ENABLED__EXPR]
      set dynamic_ranges      [table get private_params -> $param -> __DYNAMIC_RANGES]
      set allowed_ranges      [table get private_params -> $param -> ALLOWED_RANGES]
      set allowed_ranges_expr [table get private_params -> $param -> ALLOWED_RANGES__EXPR]
      set type                [table get private_params -> $param -> TYPE]
      set default_value       [table get private_params -> $param -> DEFAULT_VALUE]

      set common_families [lintersect $ip_families $param_families]
      if {$param_families == "NOVAL" || [lequal $common_families $ip_families]} {
      } elseif {[llength $common_families] == 0} {
         table unset private_params $param
         continue
      } else {
         if {!([string is false $visible] && $visible_expr == "NOVAL")} {
            if {$visible_expr != "NOVAL"} {
               table set private_params -> $param -> VISIBLE__EXPR "\[expr {$visible_expr}\] && \[table get device_features -> family -> VALUE\] in {$param_families}"
            } else {
               table set private_params -> $param -> VISIBLE__EXPR "                            \[table get device_features -> family -> VALUE\] in {$param_families}"
            }
         }
         if {!([string is false $enabled] && $enabled_expr == "NOVAL")} {
            if {$enabled_expr != "NOVAL"} {
               table set private_params -> $param -> ENABLED__EXPR "\[expr {$enabled_expr}\] && \[table get device_features -> family -> VALUE\] in {$param_families}"
            } else {
               table set private_params -> $param -> ENABLED__EXPR "                            \[table get device_features -> family -> VALUE\] in {$param_families}"
            }
         }
      }

      if {[string is true $dynamic_ranges]} {
         assert {$allowed_ranges == "NOVAL" && $allowed_ranges_expr == "NOVAL"} "Cannot set dynamic allowed ranges for parameter=$param because ALLOWED_RANGES has been explicitly set"

         set range_table "range__${param}"

         table set private_params -> $param -> ALLOWED_RANGES [table rows $range_table]

         table set private_params -> $param -> ALLOWED_RANGES__EXPR "\[::mem_ss_pkg::util::get_dynamic_ranges $param\]"

         set default_value [lindex [table rows $range_table] 0]
         if {[string match -nocase "*_list" $type]} {
            table set private_params -> $param -> DEFAULT_VALUE [list $default_value]
            set display_hint [table get private_params -> $param -> DISPLAY_HINT]
            if {$display_hint == "NOVAL"} {
               set display_hint "table_value:${default_value}"
            } else {
               append display_hint " table_value:${default_value}"
            }
            table set private_params -> $param -> DISPLAY_HINT $display_hint
         } else {
            table set private_params -> $param -> DEFAULT_VALUE $default_value
         }
      }
   }

   table clone parameters private_params
   foreach param [table rows private_params] {
      table unset private_params $param
   }
}

proc ::mem_ss_pkg::util::get_dynamic_ranges {param} {
   set param_type       [table get parameters -> $param -> TYPE]
   set is_list_datatype [string match -nocase "*_list" $param_type]
   set param_val        [table get parameters -> $param -> VALUE]

   set range_table "range__${param}"

   set dependent_params [table cols $range_table "param__*"]

   set allowed_ranges      [list]
   set allowed_ranges_list [lrepeat [llength $param_val] [list]] ;
   set validate_allowed_ranges_list 0

   foreach range [table rows $range_table] {
      set enabled [table get $range_table -> $range -> ENABLED]

      if {$enabled == "NOVAL" || $enabled} {
         set compat_list [list 1] ;

         foreach dependent_param_ $dependent_params {
            set dependent_param        [string range $dependent_param_ [string length "param__"] end] ;# remove the "param__" prefix
            set dependent_param_exists [llength [table rows parameters $dependent_param]]
            if {$dependent_param_exists <= 0} { continue }
            set dependent_param_type   [table get parameters -> $dependent_param -> TYPE]
            set dependent_is_list      [string match -nocase "*_list" $dependent_param_type]
            set dependent_param_val    [table get parameters -> $dependent_param -> VALUE]
            set dependent_ranges       [table get $range_table -> $range -> $dependent_param_]

            if {!$dependent_is_list} {
               set dependent_param_val [list $dependent_param_val]
            }

            foreach v $dependent_param_val \
                    i [range [llength $dependent_param_val]] {
               set compat [expr {$dependent_ranges == "NOVAL"}]
               foreach dependent_range $dependent_ranges {
                  incr compat [string match $dependent_range $v]
               }
               set compat [expr {$compat > 0}]
               if {$i < [llength $compat_list]} {
                  lset compat_list $i [expr {[lindex $compat_list $i] & $compat}]
               } else {
                  lappend compat_list $compat
               }
            }
         }

         if {$is_list_datatype && [llength $param_val] == [llength $compat_list]} {
            foreach c $compat_list \
                    i [range [llength $compat_list]] {
               if {$c} {
                  lset allowed_ranges_list $i end+1 $range
                  set validate_allowed_ranges_list 1
               }
            }
            if {1 in $compat_list} {
               lappend allowed_ranges $range
            }
         } else {
            if {!(0 in $compat_list)} {
               lappend allowed_ranges $range
            }
         }
      } ;
   } ;

   if {$validate_allowed_ranges_list} {
      foreach sub_val         $param_val \
              allowed_ranges_ $allowed_ranges_list \
              i               [range [llength $param_val]] {
         if {!($sub_val in $allowed_ranges_)} {
            send_message error "<html><b>\"[pname $param]\" ($param)</b> (item $i) $sub_val is out of range: [join $allowed_ranges_ {, }]</html>"
         }
      }
   }

   return $allowed_ranges
}
